/* Strict hidden override requirement */
[hidden] {
  display: none !important;
}

:root {
  --color-bg: #14182e;
  --color-surface: #262b44;
  --color-primary: #38b764;
  --color-accent: #e43b44;
  --color-text: #f4f4f4;
  --color-dim: #738290;
  --pixel-border: 4px solid #0b0c10;
  --font-stack: "Courier New", Courier, monospace, system-ui;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background-color: var(--color-bg);
  color: var(--color-text);
  font-family: var(--font-stack);
  font-size: 16px;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.app-container {
  background-color: var(--color-surface);
  border: var(--pixel-border);
  box-shadow: 8px 8px 0px #0b0c10;
  width: 100%;
  max-width: 420px;
  min-width: 320px;
  padding: 24px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 20px;
}

.timer-header {
  text-align: center;
}

.app-title {
  font-size: 24px;
  letter-spacing: 2px;
  text-transform: uppercase;
  margin-bottom: 8px;
  color: var(--color-text);
  text-shadow: 2px 2px 0px #0b0c10;
}

.session-tag {
  display: inline-block;
  padding: 4px 12px;
  font-size: 16px;
  font-weight: bold;
  letter-spacing: 1px;
  border: 2px solid #0b0c10;
  background: var(--color-primary);
  color: #0b0c10;
  text-transform: uppercase;
}

.session-tag.break {
  background: #3b8beb;
}

.session-tag.long-break {
  background: #fbb954;
}

.timer-display-card {
  background-color: #0b0c10;
  border: 3px solid var(--color-dim);
  padding: 16px;
  width: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
}

#pixel-canvas {
  image-rendering: pixelated;
  background-color: #040406;
  border: 2px solid var(--color-dim);
  width: 256px;
  max-width: 100%;
  height: auto;
}

.time-digits {
  font-size: 44px;
  font-weight: bold;
  letter-spacing: 4px;
  color: var(--color-text);
  text-shadow: 0 0 4px rgba(255, 255, 255, 0.4);
}

.cycle-info {
  font-size: 16px;
  color: var(--color-dim);
  letter-spacing: 1px;
}

.controls {
  display: flex;
  gap: 12px;
  width: 100%;
  justify-content: center;
  flex-wrap: wrap;
}

.btn {
  font-family: inherit;
  font-size: 16px;
  font-weight: bold;
  text-transform: uppercase;
  padding: 10px 18px;
  cursor: pointer;
  border: 3px solid #0b0c10;
  box-shadow: 3px 3px 0px #0b0c10;
  background: var(--color-dim);
  color: #0b0c10;
  transition: transform 0.05s ease, box-shadow 0.05s ease;
}

.btn:hover:not(:disabled) {
  filter: brightness(1.15);
}

.btn:focus-visible {
  outline: 3px solid #fbb954;
  outline-offset: 2px;
}

.btn:active:not(:disabled) {
  transform: translate(2px, 2px);
  box-shadow: 1px 1px 0px #0b0c10;
}

.btn:disabled {
  opacity: 0.4;
  cursor: not-allowed;
  box-shadow: none;
}

.btn-primary {
  background-color: var(--color-primary);
}

.btn-secondary {
  background-color: var(--color-accent);
  color: #ffffff;
}

.btn-subtle {
  background-color: #a2aab5;
}

(function () {
  const WORK_SECONDS = 25 * 60;
  const SHORT_BREAK_SECONDS = 5 * 60;
  const LONG_BREAK_SECONDS = 15 * 60;

  const MODES = {
    WORK: 'Work',
    SHORT_BREAK: 'Break',
    LONG_BREAK: 'Break (Long)'
  };

  let currentMode = MODES.WORK;
  let workSessionsCompleted = 0;
  let remainingSeconds = WORK_SECONDS;
  let timerInterval = null;
  let isRunning = false;

  // Elements
  const timeDisplay = document.getElementById('time-display');
  const modeLabel = document.getElementById('mode-label');
  const cycleDisplay = document.getElementById('cycle-display');
  const btnStart = document.getElementById('btn-start');
  const btnPause = document.getElementById('btn-pause');
  const btnReset = document.getElementById('btn-reset');
  const canvas = document.getElementById('pixel-canvas');
  const ctx = canvas.getContext('2d');

  function formatTime(totalSeconds) {
    const mins = Math.floor(totalSeconds / 60);
    const secs = totalSeconds % 60;
    return `${String(mins).padStart(2, '0')}:${String(secs).padStart(2, '0')}`;
  }

  function updateUI() {
    timeDisplay.textContent = formatTime(remainingSeconds);
    document.title = `${formatTime(remainingSeconds)} - ${currentMode}`;
    modeLabel.textContent = currentMode;

    modeLabel.className = 'session-tag';
    if (currentMode === MODES.SHORT_BREAK) {
      modeLabel.classList.add('break');
    } else if (currentMode === MODES.LONG_BREAK) {
      modeLabel.classList.add('long-break');
    }

    cycleDisplay.textContent = `Completed Sessions: ${workSessionsCompleted % 4}/4 (Total: ${workSessionsCompleted})`;
    btnStart.disabled = isRunning;
    btnPause.disabled = !isRunning;
    renderCanvas();
  }

  function getTotalDurationForMode(mode) {
    if (mode === MODES.WORK) return WORK_SECONDS;
    if (mode === MODES.SHORT_BREAK) return SHORT_BREAK_SECONDS;
    return LONG_BREAK_SECONDS;
  }

  function renderCanvas() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    const total = getTotalDurationForMode(currentMode);
    const progress = Math.max(0, Math.min(1, 1 - remainingSeconds / total));

    // Background grid
    ctx.fillStyle = '#14182e';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // Progress bar frame
    const barX = 14;
    const barY = 44;
    const barW = 100;
    const barH = 10;

    ctx.fillStyle = '#0b0c10';
    ctx.fillRect(barX - 2, barY - 2, barW + 4, barH + 4);

    const fillW = Math.round(barW * progress);
    ctx.fillStyle = currentMode === MODES.WORK ? '#38b764' : '#3b8beb';
    ctx.fillRect(barX, barY, fillW, barH);

    // Pixel sprite/symbol
    drawPixelGraphic(currentMode, isRunning);
  }

  function drawPixelGraphic(mode, active) {
    const centerX = 64;
    const centerY = 20;

    if (mode === MODES.WORK) {
      // Pixel hourglass or monitor
      ctx.fillStyle = active ? '#e43b44' : '#738290';
      ctx.fillRect(centerX - 10, centerY - 8, 20, 16);
      ctx.fillStyle = '#262b44';
      ctx.fillRect(centerX - 8, centerY - 6, 16, 12);
      ctx.fillStyle = '#38b764';
      ctx.fillRect(centerX - 4, centerY - 2, 8, 4);
    } else {
      // Pixel coffee mug
      ctx.fillStyle = '#fbb954';
      ctx.fillRect(centerX - 8, centerY - 6, 14, 14);
      ctx.fillRect(centerX + 6, centerY - 4, 4, 8);
      ctx.fillStyle = '#262b44';
      ctx.fillRect(centerX + 7, centerY - 2, 2, 4);
      ctx.fillStyle = '#ffffff';
      if (active) {
        ctx.fillRect(centerX - 4, centerY - 10, 2, 3);
        ctx.fillRect(centerX + 2, centerY - 10, 2, 3);
      }
    }
  }

  function nextMode() {
    if (currentMode === MODES.WORK) {
      workSessionsCompleted += 1;
      if (workSessionsCompleted % 4 === 0) {
        currentMode = MODES.LONG_BREAK;
        remainingSeconds = LONG_BREAK_SECONDS;
      } else {
        currentMode = MODES.SHORT_BREAK;
        remainingSeconds = SHORT_BREAK_SECONDS;
      }
    } else {
      currentMode = MODES.WORK;
      remainingSeconds = WORK_SECONDS;
    }
  }

  function tick() {
    if (remainingSeconds > 0) {
      remainingSeconds -= 1;
    } else {
      pauseTimer();
      nextMode();
    }
    updateUI();
  }

  function startTimer() {
    if (isRunning) return;
    isRunning = true;
    timerInterval = setInterval(tick, 1000);
    updateUI();
  }

  function pauseTimer() {
    if (!isRunning) return;
    isRunning = false;
    if (timerInterval) {
      clearInterval(timerInterval);
      timerInterval = null;
    }
    updateUI();
  }

  function resetTimer() {
    pauseTimer();
    currentMode = MODES.WORK;
    remainingSeconds = WORK_SECONDS;
    workSessionsCompleted = 0;
    updateUI();
  }

  // Event Listeners
  btnStart.addEventListener('click', startTimer);
  btnPause.addEventListener('click', pauseTimer);
  btnReset.addEventListener('click', resetTimer);

  // Initial render
  updateUI();
})();
